<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { apiRequest } from './api'
import { parseAcpArgs, parseAcpEnv, stringifyAcpEnv } from './acp'

type AcpAgent = { enabled: boolean; command: string; args: string[]; env: Record<string, string>; trusted: boolean; tool_parse_mode: 'call_title' | 'update_detail' | 'call_detail'; stdio_buffer_limit_bytes: number }
type NodeRuntime = { node_path?: string; effective_node_path?: string; available?: boolean; node_version?: string; reason?: string; candidates?: Array<{ key: string; node_path: string; available: boolean; node_version?: string; reason?: string }> }
type Draft = AcpAgent & { key: string; argsText: string; envText: string }
const builtins = ['opencode', 'qwen_code', 'claude_code', 'codex']
const agents = ref<Record<string, AcpAgent>>({})
const filter = ref<'all' | 'builtin' | 'custom'>('all')
const draft = ref<Draft | null>(null)
const originalKey = ref('')
const nodeRuntime = ref<NodeRuntime | null>(null)
const nodePath = ref('')
const nodeOpen = ref(false)
const loading = ref(false), saving = ref(false), nodeSaving = ref(false)
const error = ref(''), notice = ref('')
const visibleAgents = computed(() => Object.entries(agents.value)
  .filter(([key]) => filter.value === 'all' || (filter.value === 'builtin') === builtins.includes(key))
  .sort(([left, a], [right, b]) => Number(Boolean(b.enabled)) - Number(Boolean(a.enabled)) || Number(builtins.includes(right)) - Number(builtins.includes(left)) || left.localeCompare(right)))

function defaultDraft(key = ''): Draft { return { key, enabled: true, command: '', args: [], env: {}, trusted: true, tool_parse_mode: 'call_title', stdio_buffer_limit_bytes: 50 * 1024 * 1024, argsText: '', envText: '' } }
function makeDraft(key: string, agent: AcpAgent) { return { ...agent, key, argsText: (agent.args || []).join('\n'), envText: stringifyAcpEnv(agent.env) } }
async function refresh() { loading.value = true; error.value = ''; try { const config = await apiRequest<{ agents?: Record<string, AcpAgent> }>('/config/acp'); agents.value = config.agents || {} } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not load ACP agents.' } finally { loading.value = false } }
async function openNodeSettings() { nodeOpen.value = true; try { nodeRuntime.value = await apiRequest<NodeRuntime>('/config/acp/node-runtime'); nodePath.value = nodeRuntime.value.node_path || nodeRuntime.value.effective_node_path || '' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not load the Node runtime.' } }
async function saveNode() { nodeSaving.value = true; error.value = ''; try { nodeRuntime.value = await apiRequest<NodeRuntime>('/config/acp/node-runtime', { method: 'PUT', body: JSON.stringify({ node_path: nodePath.value.trim() }) }); nodeOpen.value = false; notice.value = 'Node runtime saved.' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not save the Node runtime.' } finally { nodeSaving.value = false } }
function edit(key: string, agent: AcpAgent) { error.value = ''; notice.value = ''; originalKey.value = key; draft.value = makeDraft(key, agent) }
function create() { error.value = ''; notice.value = ''; originalKey.value = ''; draft.value = defaultDraft() }
async function save() { const value = draft.value; if (!value) return; const key = value.key.trim(); if (!/^[A-Za-z0-9_-]+$/.test(key)) { error.value = 'The agent key may contain letters, numbers, underscores, and hyphens only.'; return } if (!originalKey.value && agents.value[key]) { error.value = 'An ACP agent with this key already exists.'; return } try { value.args = parseAcpArgs(value.argsText); value.env = parseAcpEnv(value.envText) } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Invalid ACP environment.'; return } saving.value = true; error.value = ''; try { const saved: AcpAgent = { enabled: value.enabled, command: value.command.trim(), args: value.args, env: value.env, trusted: value.trusted, tool_parse_mode: value.tool_parse_mode, stdio_buffer_limit_bytes: Number(value.stdio_buffer_limit_bytes) }; if (!saved.command) { error.value = 'Command is required.'; return } if (originalKey.value && originalKey.value === key) await apiRequest(`/config/acp/${encodeURIComponent(key)}`, { method: 'PUT', body: JSON.stringify(saved) }); else { const next = { ...agents.value }; if (originalKey.value) delete next[originalKey.value]; next[key] = saved; await apiRequest('/config/acp', { method: 'PUT', body: JSON.stringify({ agents: next }) }) } await refresh(); draft.value = null; notice.value = 'ACP agent saved.' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not save the ACP agent.' } finally { saving.value = false } }
async function remove() { const key = originalKey.value; if (!key || builtins.includes(key) || !window.confirm(`Delete ACP agent ${key}?`)) return; try { const next = { ...agents.value }; delete next[key]; await apiRequest('/config/acp', { method: 'PUT', body: JSON.stringify({ agents: next }) }); await refresh(); draft.value = null; notice.value = 'ACP agent deleted.' } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Could not delete the ACP agent.' } }
onMounted(() => void refresh())
</script>

<template>
  <section class="settings-page acp-page">
    <header class="settings-heading"><div><p class="eyebrow">AGENT</p><h1>ACP</h1></div><div class="skills-editor-actions"><button @click="openNodeSettings">Node runtime</button><button class="primary" @click="create">New ACP agent</button></div></header>
    <p v-if="error" class="inline-error" role="alert">{{ error }}</p><p v-if="notice" class="success-notice">{{ notice }}</p>
    <nav class="apps-tabs" aria-label="ACP filters"><button v-for="item in [['all','All'],['builtin','Built-in'],['custom','Custom']]" :key="item[0]" :class="{ active: filter === item[0] }" @click="filter = item[0] as typeof filter">{{ item[1] }}</button></nav>
    <p v-if="loading" class="muted">Loading ACP agents…</p><p v-else-if="!visibleAgents.length" class="muted">No ACP agents match this filter.</p>
    <div class="acp-grid"><button v-for="[key, agent] in visibleAgents" :key="key" class="acp-card" :class="{ disabled: !agent.enabled }" @click="edit(key, agent)"><span class="acp-card-status">{{ agent.enabled ? '● Enabled' : '○ Disabled' }}</span><strong>{{ key }}</strong><small>{{ builtins.includes(key) ? 'Built-in' : 'Custom' }}</small><span>{{ agent.command || 'Command not set' }}</span><code>{{ agent.args.join(' ') || 'No arguments' }}</code></button></div>
    <div v-if="draft" class="modal-backdrop" role="dialog" aria-modal="true" aria-label="ACP agent editor"><form class="acp-editor" @submit.prevent="save"><header><h2>{{ originalKey ? `Configure ${originalKey}` : 'Create ACP agent' }}</h2><button type="button" class="icon-button" @click="draft = null">×</button></header><label>Agent key<input v-model="draft.key" :disabled="Boolean(originalKey && builtins.includes(originalKey))" required /></label><label class="skills-checkbox"><input v-model="draft.enabled" type="checkbox" /> Enabled</label><label>Command<input v-model="draft.command" required placeholder="npx" /></label><label>Arguments <small>One argument per line</small><textarea v-model="draft.argsText" rows="4" /></label><label>Environment <small>One KEY=value entry per line</small><textarea v-model="draft.envText" rows="4" /></label><label class="skills-checkbox"><input v-model="draft.trusted" type="checkbox" /> Trusted runner</label><label>Tool parse mode<select v-model="draft.tool_parse_mode"><option value="call_title">call_title</option><option value="update_detail">update_detail</option><option value="call_detail">call_detail</option></select></label><label>Stdio buffer limit (bytes)<input v-model.number="draft.stdio_buffer_limit_bytes" min="1" type="number" /></label><footer><button v-if="originalKey && !builtins.includes(originalKey)" type="button" class="danger" @click="remove">Delete</button><span /><button type="button" @click="draft = null">Cancel</button><button type="submit" class="primary" :disabled="saving">{{ saving ? 'Saving…' : 'Save' }}</button></footer></form></div>
    <div v-if="nodeOpen" class="modal-backdrop" role="dialog" aria-modal="true" aria-label="Node runtime"><form class="acp-editor node-editor" @submit.prevent="saveNode"><header><h2>ACP Node runtime</h2><button type="button" class="icon-button" @click="nodeOpen = false">×</button></header><p v-if="nodeRuntime?.node_version" class="muted">Detected version: {{ nodeRuntime.node_version }}</p><p v-if="nodeRuntime?.reason" class="inline-error">{{ nodeRuntime.reason }}</p><label>Node executable path<input v-model="nodePath" placeholder="Use the detected runtime" /></label><div v-if="nodeRuntime?.candidates?.length" class="data-list"><button v-for="candidate in nodeRuntime.candidates" :key="candidate.key" type="button" :disabled="!candidate.available" @click="nodePath = candidate.node_path">{{ candidate.key }} · {{ candidate.node_path || 'Unavailable' }} {{ candidate.node_version ? `(${candidate.node_version})` : '' }}</button></div><footer><span /><button type="button" @click="nodeOpen = false">Cancel</button><button class="primary" :disabled="nodeSaving" type="submit">{{ nodeSaving ? 'Saving…' : 'Save runtime' }}</button></footer></form></div>
  </section>
</template>
